module tb;
    reg a, b, c;
    wire out;

    TopModule uut (
        .a(a),
        .b(b),
        .c(c),
        .out(out)
    );

    initial begin
        integer i;
        reg expected;
        for (i = 0; i < 8; i = i + 1) begin
            {a, b, c} = i[2:0];
            // Independent reference model: out is 1 except when a=0, b=0, c=0
            expected = (i != 3'b000);
            #1;
            if (out !== expected) begin
                $display("SELFTEST FAIL: a=%b b=%b c=%b -> got %b, expected %b", a, b, c, out, expected);
                $finish;
            end
        end
        $display("SELFTEST PASS");
        $finish;
    end
endmodule
